{"id":"c1","type":"files_changed","basis":"round_up floored instead of ceiling (SPEC §3); format_duration did not zero-pad minutes (SPEC §2).","command":null,"exit_code":null,"passed":null,"failed":null,"paths":["billable/rounding.py","billable/durations.py"],"commit":"eaf5170","depends_on":[],"status":"done"},
